CREATE DATABASE IF NOT EXISTS loan_db;
USE loan_db;

DROP TABLE IF EXISTS monthly_snapshot;
DROP TABLE IF EXISTS loan_accounts;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS branches;
DROP TABLE IF EXISTS provision_norms;

CREATE TABLE branches (
    branch_id    INTEGER PRIMARY KEY,
    branch_name   VARCHAR(100) NOT NULL,
    city          VARCHAR(20) NOT NULL,
    state         VARCHAR(20) NOT NULL,
    region        VARCHAR(20) NOT NULL CHECK (region IN ('North','South','East','West','Central'))
);

CREATE TABLE customers (
    customer_id      INTEGER PRIMARY KEY,
    age              INTEGER NOT NULL,
    employment_type  TEXT NOT NULL CHECK (employment_type IN ('Salaried','Self-Employed')),
    annual_income    INTEGER NOT NULL            -- INR
);

CREATE TABLE loan_accounts (
    loan_id                     INTEGER PRIMARY KEY,
    customer_id                 INTEGER NOT NULL REFERENCES customers(customer_id),
    branch_id                   INTEGER NOT NULL REFERENCES branches(branch_id),
    product_type                 VARCHAR(20) NOT NULL,
    disbursal_date              VARCHAR(20) NOT NULL,   -- ISO yyyy-mm-dd
    sanctioned_amount           INTEGER NOT NULL,-- INR
    tenure_months               INTEGER NOT NULL,
    interest_rate               REAL NOT NULL,   -- % p.a.
    credit_score_at_origination INTEGER NOT NULL,-- bureau score (300-900)
    secured_flag                INTEGER NOT NULL CHECK (secured_flag IN (0,1))
);

-- One row per loan per month-end. dpd = days past due at month-end.
CREATE TABLE monthly_snapshot (
    loan_id               INTEGER NOT NULL REFERENCES loan_accounts(loan_id),
    snapshot_month  VARCHAR(7) NOT NULL,
    months_on_book        INTEGER NOT NULL,      -- MOB
    outstanding_principal INTEGER NOT NULL,      -- INR
    dpd                   INTEGER NOT NULL,
    PRIMARY KEY (loan_id, snapshot_month)
);

-- Illustrative provisioning matrix (assumption - not RBI's exact schedule)
CREATE TABLE provision_norms (
    dpd_bucket      VARCHAR(20) PRIMARY KEY,
    min_dpd        INTEGER NOT NULL,
    max_dpd        INTEGER NOT NULL,
    provision_rate REAL NOT NULL,
    asset_class    TEXT NOT NULL
);

CREATE INDEX idx_snap_month ON monthly_snapshot(snapshot_month);
CREATE INDEX idx_loans_branch ON loan_accounts(branch_id);
CREATE INDEX idx_loans_product ON loan_accounts(product_type);

